// Shared helpers for the Trail Runner 2 product page tests.
//
// These helpers define the UI contract the implementation must satisfy.
// Locators are role- and name-based (what assistive technology sees), so the
// tests stay independent of markup and CSS.

import { expect } from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'

export const PRODUCT_PATH = '/products/trail-runner-2'
export const PRODUCT_NAME = 'Trail Runner 2'

// WCAG 2.2 Level A and AA success criteria, plus axe's best-practice rules
// (landmarks, page heading, etc.), which the APG patterns rely on.
export const WCAG_TAGS = [
  'wcag2a',
  'wcag21a',
  'wcag22a',
  'wcag2aa',
  'wcag21aa',
  'wcag22aa',
  'best-practice',
]

export async function openProductPage(page) {
  await page.goto(PRODUCT_PATH)
  await expect(
    page.getByRole('heading', { level: 1, name: PRODUCT_NAME }),
  ).toBeVisible()
}

export async function expectNoAxeViolations(page, label) {
  const { violations } = await new AxeBuilder({ page })
    .withTags(WCAG_TAGS)
    .analyze()
  const summary = violations.map(
    (v) =>
      `${v.id} [${v.impact}] ${v.help}: ${v.nodes
        .map((n) => n.target.join(' '))
        .join(', ')}`,
  )
  expect(summary, `axe violations (${label})`).toEqual([])
}

// Store header
export function cartControl(page) {
  const banner = page.getByRole('banner')
  return banner
    .getByRole('link', { name: /cart/i })
    .or(banner.getByRole('button', { name: /cart/i }))
}

export async function readCartCount(page) {
  const text = await cartControl(page).innerText()
  const match = text.match(/\d+/)
  expect(match, 'cart control shows an item count').not.toBeNull()
  return Number(match[0])
}

// Photos (APG carousel: a labelled group/region with prev/next buttons)
export function photoCarousel(page) {
  return page
    .getByRole('group', { name: /photo/i })
    .or(page.getByRole('region', { name: /photo/i }))
}

// Identity of the one photo currently shown (src + alt).
export async function visiblePhotoKey(carousel) {
  const visible = carousel.locator('img:visible')
  if ((await visible.count()) !== 1) return 'not exactly one visible photo'
  return visible.evaluate((img) => `${img.getAttribute('src')}|${img.alt}`)
}

export function nextPhotoButton(carousel) {
  return carousel.getByRole('button', { name: /next/i })
}

export function previousPhotoButton(carousel) {
  return carousel.getByRole('button', { name: /previous|prev/i })
}

// Price
export function priceText(page) {
  return page.getByRole('main').getByText(/(\$|€|£)\s?\d/).first()
}

export function priceInfoButton(page) {
  return page.getByRole('main').getByRole('button', { name: /price/i })
}

// Colour (APG radio group; the change control is a disclosure button)
export function colorRadioGroup(page) {
  return page.getByRole('radiogroup', { name: /colou?r/i })
}

export function colorRadios(page) {
  return page.getByRole('radio', { name: /^(blue|black|grey)$/i })
}

export function changeColorButton(page) {
  return page.getByRole('button', { name: /colou?r/i })
}

// Size (APG select-only combobox with a listbox popup)
export function sizeCombobox(page) {
  return page.getByRole('combobox', { name: /size/i })
}

export function sizeListbox(page) {
  return page.getByRole('listbox')
}

export function sizeGuideTrigger(page) {
  return page
    .getByRole('button', { name: /size guide/i })
    .or(page.getByRole('link', { name: /size guide/i }))
}

export function sizeGuideDialog(page) {
  return page.getByRole('dialog', { name: /size guide/i })
}

export async function openSizeList(page) {
  await sizeCombobox(page).click()
  await expect(sizeListbox(page)).toBeVisible()
}

// Chooses the first size that is not sold out.
export async function chooseFirstAvailableSize(page) {
  await openSizeList(page)
  await sizeListbox(page)
    .getByRole('option', { disabled: false })
    .first()
    .click()
  await expect(sizeListbox(page)).toBeHidden()
}

// Quantity (APG spinbutton)
export function quantityInput(page) {
  return page.getByRole('spinbutton', { name: /quantity/i })
}

// Add to cart and wishlist
export function addToCartButton(page) {
  return page.getByRole('button', { name: /add to cart/i })
}

export function wishlistButton(page) {
  return page.getByRole('button', { name: /wishlist/i })
}

// More information (APG tabs)
export function infoTablist(page) {
  return page.getByRole('tablist')
}

export function infoTab(page, name) {
  return infoTablist(page).getByRole('tab', { name })
}

// Questions (APG accordion inside a labelled region)
export function questionsRegion(page) {
  return page.getByRole('region', { name: /questions/i })
}

export function questionButtons(page) {
  return questionsRegion(page).getByRole('button')
}

// Footer
export function pageFooter(page) {
  return page.getByRole('contentinfo')
}
