// Functional tests for REQUIREMENTS.md: "Product page: Trail Runner 2".
import { test, expect } from '@playwright/test'
import {
  PRODUCT_PATH,
  PRODUCT_NAME,
  openProductPage,
  cartControl,
  readCartCount,
  photoCarousel,
  visiblePhotoKey,
  nextPhotoButton,
  previousPhotoButton,
  priceText,
  priceInfoButton,
  colorRadioGroup,
  colorRadios,
  changeColorButton,
  sizeCombobox,
  sizeListbox,
  sizeGuideTrigger,
  sizeGuideDialog,
  openSizeList,
  chooseFirstAvailableSize,
  quantityInput,
  addToCartButton,
  wishlistButton,
  infoTablist,
  infoTab,
  questionsRegion,
  questionButtons,
  pageFooter,
} from './helpers.js'

test.describe('Product page: Trail Runner 2', () => {
  test('is reached from the homepage link and is served at /products/trail-runner-2', async ({
    page,
  }) => {
    await page.goto('/')
    await page.getByRole('link', { name: PRODUCT_NAME }).click()
    await expect(page).toHaveURL(new RegExp(`${PRODUCT_PATH}$`))
    await expect(
      page.getByRole('heading', { level: 1, name: PRODUCT_NAME }),
    ).toBeVisible()
    await expect(page).toHaveTitle(new RegExp(PRODUCT_NAME))
  })

  test.describe('Store', () => {
    test('shows the store name', async ({ page }) => {
      await openProductPage(page)
      await expect(page.getByRole('banner')).toContainText('Stride')
    })

    test('shows how many items are in the cart', async ({ page }) => {
      await openProductPage(page)
      await expect(cartControl(page)).toBeVisible()
      await expect(cartControl(page)).toHaveAccessibleName(/\d+/)
      expect(await readCartCount(page)).toBeGreaterThanOrEqual(0)
    })
  })

  test.describe('Menu', () => {
    test('offers the main store sections at the top of the page', async ({
      page,
    }) => {
      await openProductPage(page)
      const menu = page
        .getByRole('navigation')
        .filter({ has: page.getByRole('link', { name: 'Men' }) })

      for (const section of ['Men', 'Women', 'Kids']) {
        await expect(menu.getByRole('link', { name: section })).toBeVisible()
      }

      const menuBox = await menu.boundingBox()
      const headingBox = await page
        .getByRole('heading', { level: 1, name: PRODUCT_NAME })
        .boundingBox()
      expect(menuBox.y).toBeLessThan(headingBox.y)
    })
  })

  test.describe('Path', () => {
    test('shows Shop, Trail and Trail Runner 2 in order, ending on the current product', async ({
      page,
    }) => {
      await openProductPage(page)
      const path = page.getByRole('navigation', { name: /breadcrumb/i })
      await expect(path).toBeVisible()

      const items = await path.getByRole('listitem').allInnerTexts()
      expect(items.map((t) => t.trim())).toEqual([
        'Shop',
        'Trail',
        PRODUCT_NAME,
      ])
      await expect(
        path.getByRole('link', { name: PRODUCT_NAME }),
      ).toHaveCount(0)
    })

    test('lets the shopper go back to any earlier step', async ({ page }) => {
      await openProductPage(page)
      const path = page.getByRole('navigation', { name: /breadcrumb/i })

      for (const step of ['Shop', 'Trail']) {
        await expect(path.getByRole('link', { name: step })).toBeVisible()
      }

      await path.getByRole('link', { name: 'Trail' }).click()
      await expect(page).not.toHaveURL(new RegExp(`${PRODUCT_PATH}$`))
    })
  })

  test.describe('Photos', () => {
    test('shows one photo at a time', async ({ page }) => {
      await openProductPage(page)
      const carousel = photoCarousel(page)
      await expect(carousel).toBeVisible()
      expect(await carousel.locator('img').count()).toBeGreaterThan(1)
      await expect(carousel.locator('img:visible')).toHaveCount(1)
    })

    test('moves to the next photo', async ({ page }) => {
      await openProductPage(page)
      const carousel = photoCarousel(page)
      const first = await visiblePhotoKey(carousel)

      await nextPhotoButton(carousel).click()
      await expect
        .poll(() => visiblePhotoKey(carousel))
        .not.toBe(first)
    })

    test('goes back to the first photo after the last one', async ({
      page,
    }) => {
      await openProductPage(page)
      const carousel = photoCarousel(page)
      const first = await visiblePhotoKey(carousel)
      const total = await carousel.locator('img').count()

      for (let i = 1; i < total; i++) {
        await nextPhotoButton(carousel).click()
      }
      await expect
        .poll(() => visiblePhotoKey(carousel))
        .not.toBe(first)

      await nextPhotoButton(carousel).click()
      await expect.poll(() => visiblePhotoKey(carousel)).toBe(first)
    })

    test('moves to the previous photo', async ({ page }) => {
      await openProductPage(page)
      const carousel = photoCarousel(page)
      const first = await visiblePhotoKey(carousel)

      await nextPhotoButton(carousel).click()
      await expect.poll(() => visiblePhotoKey(carousel)).not.toBe(first)

      await previousPhotoButton(carousel).click()
      await expect.poll(() => visiblePhotoKey(carousel)).toBe(first)
    })
  })

  test.describe('Price', () => {
    test('shows the price with its currency', async ({ page }) => {
      await openProductPage(page)
      await expect(priceText(page)).toBeVisible()
    })

    test('explains with a small "i" that the price includes taxes', async ({
      page,
    }) => {
      await openProductPage(page)
      const info = priceInfoButton(page)
      await expect(info).toBeVisible()

      await info.hover()
      await expect(page.getByRole('tooltip')).toContainText(/includes?.*tax/i)
    })

    test('shows the taxes note when the "i" is focused from the keyboard', async ({
      page,
    }) => {
      await openProductPage(page)
      await priceInfoButton(page).focus()
      await expect(page.getByRole('tooltip')).toContainText(/includes?.*tax/i)
    })
  })

  test.describe('Colour', () => {
    test('shows only the chosen colour, with a round swatch, until the shopper changes it', async ({
      page,
    }) => {
      await openProductPage(page)
      await expect(colorRadioGroup(page)).toBeVisible()
      await expect(colorRadios(page).filter({ visible: true })).toHaveCount(1)
      await expect(
        colorRadios(page).filter({ visible: true, checked: true }),
      ).toHaveCount(1)

      const swatch = colorRadios(page).filter({ visible: true }).first()
      const { width, height, radius } = await swatch.evaluate((el) => {
        const r = el.getBoundingClientRect()
        return {
          width: r.width,
          height: r.height,
          radius: parseFloat(getComputedStyle(el).borderTopLeftRadius),
        }
      })
      expect(Math.abs(width - height)).toBeLessThan(1)
      expect(radius).toBeGreaterThanOrEqual(width / 2 - 0.5)
    })

    test('lets the shopper change to blue, black or grey', async ({ page }) => {
      await openProductPage(page)
      await changeColorButton(page).click()

      for (const color of ['Blue', 'Black', 'Grey']) {
        await expect(
          colorRadios(page).getByRole('radio', { name: color }),
        ).toBeVisible()
      }
    })

    test('shows the newly chosen colour after a change', async ({ page }) => {
      await openProductPage(page)
      await changeColorButton(page).click()
      await page.getByRole('radio', { name: 'Black' }).click()

      await expect(page.getByRole('radio', { name: 'Black' })).toBeChecked()
      await expect(
        colorRadios(page).filter({ visible: true, checked: true }),
      ).toHaveCount(1)
      await expect(
        colorRadios(page).filter({ visible: true, checked: true }),
      ).toHaveAccessibleName(/^black$/i)
    })
  })

  test.describe('Size', () => {
    test('shows only the chosen size; the list stays closed until the shopper opens it', async ({
      page,
    }) => {
      await openProductPage(page)
      await expect(sizeCombobox(page)).toContainText(/\d/)
      await expect(page.getByRole('option')).toHaveCount(0)
      await expect(sizeListbox(page)).toBeHidden()
    })

    test('opens the list of sizes when the shopper wants to change size', async ({
      page,
    }) => {
      await openProductPage(page)
      await openSizeList(page)
      await expect(sizeListbox(page).getByRole('option').first()).toBeVisible()
      expect(
        await sizeListbox(page).getByRole('option').count(),
      ).toBeGreaterThan(1)
    })

    test('picking a size shows it and closes the list', async ({ page }) => {
      await openProductPage(page)
      await openSizeList(page)

      const option = sizeListbox(page)
        .getByRole('option', { disabled: false })
        .nth(1)
      const optionText = (await option.innerText()).trim()
      await option.click()

      await expect(sizeListbox(page)).toBeHidden()
      await expect(sizeCombobox(page)).toContainText(optionText)
    })

    test('sold-out sizes cannot be picked', async ({ page }) => {
      await openProductPage(page)
      await openSizeList(page)

      const soldOut = sizeListbox(page).getByRole('option', { disabled: true })
      expect(await soldOut.count()).toBeGreaterThan(0)

      const before = await sizeCombobox(page).innerText()
      await soldOut.first().click()
      await expect(sizeCombobox(page)).toHaveText(before)
    })
  })

  test.describe('Size guide', () => {
    test('opens from next to the size as a size chart over the page', async ({
      page,
    }) => {
      await openProductPage(page)
      const trigger = sizeGuideTrigger(page)
      await expect(trigger).toBeVisible()

      const [triggerBox, sizeBox] = await Promise.all([
        trigger.boundingBox(),
        sizeCombobox(page).boundingBox(),
      ])
      expect(
        Math.abs(triggerBox.y + triggerBox.height / 2 -
          (sizeBox.y + sizeBox.height / 2)),
      ).toBeLessThan(120)

      await trigger.click()
      const dialog = sizeGuideDialog(page)
      await expect(dialog).toBeVisible()
      await expect(dialog.getByRole('table')).toBeVisible()
    })

    test('converts a foot length to a US or EU size', async ({ page }) => {
      await openProductPage(page)
      await sizeGuideTrigger(page).click()
      const dialog = sizeGuideDialog(page)

      await dialog.getByLabel(/foot length/i).fill('27')

      await dialog.getByRole('radio', { name: 'US' }).check()
      await dialog.getByRole('button', { name: /my size/i }).click()
      const usSize = await dialog.getByRole('status').innerText()
      expect(usSize).toMatch(/\d/)

      await dialog.getByRole('radio', { name: 'EU' }).check()
      await dialog.getByRole('button', { name: /my size/i }).click()
      const euSize = await dialog.getByRole('status').innerText()
      expect(euSize).toMatch(/\d/)

      expect(euSize).not.toBe(usSize)
    })

    test('stays open until closed, and closing returns the shopper to the page', async ({
      page,
    }) => {
      await openProductPage(page)
      await sizeGuideTrigger(page).click()
      const dialog = sizeGuideDialog(page)
      await expect(dialog).toBeVisible()

      // While the guide is open, Tab must not reach the rest of the page.
      for (let i = 0; i < 30; i++) {
        await page.keyboard.press('Tab')
        const insideDialog = await page.evaluate(
          () => !!document.activeElement?.closest('[role="dialog"]'),
        )
        expect(insideDialog).toBe(true)
      }

      await dialog.getByRole('button', { name: /close/i }).click()
      await expect(dialog).toBeHidden()
      await expect(addToCartButton(page)).toBeEnabled()
    })

    test('can be closed with the Escape key', async ({ page }) => {
      await openProductPage(page)
      await sizeGuideTrigger(page).click()
      await expect(sizeGuideDialog(page)).toBeVisible()
      await page.keyboard.press('Escape')
      await expect(sizeGuideDialog(page)).toBeHidden()
    })
  })

  test.describe('Quantity', () => {
    test('lets the shopper type how many pairs to buy', async ({ page }) => {
      await openProductPage(page)
      const quantity = quantityInput(page)
      await quantity.fill('3')
      await expect(quantity).toHaveValue('3')
    })

    test('changes quantity by one with the plus and minus controls', async ({
      page,
    }) => {
      await openProductPage(page)
      const quantity = quantityInput(page)
      await quantity.fill('2')

      await page.getByRole('button', { name: /increase quantity/i }).click()
      await expect(quantity).toHaveValue('3')

      await page.getByRole('button', { name: /decrease quantity/i }).click()
      await expect(quantity).toHaveValue('2')
    })

    test('does not go below one pair', async ({ page }) => {
      await openProductPage(page)
      const quantity = quantityInput(page)
      await quantity.fill('1')
      await page.getByRole('button', { name: /decrease quantity/i }).click()
      await expect(quantity).toHaveValue('1')
    })
  })

  test.describe('Add to cart', () => {
    test('asks for a size and does not add the shoe when no size is picked', async ({
      page,
    }) => {
      await openProductPage(page)
      const before = await readCartCount(page)

      await addToCartButton(page).click()

      await expect(
        page.getByRole('alert').filter({ hasText: /size/i }),
      ).toBeVisible()
      expect(await readCartCount(page)).toBe(before)
    })

    test('adds the chosen quantity to the cart and confirms it', async ({
      page,
    }) => {
      await openProductPage(page)
      await chooseFirstAvailableSize(page)
      await quantityInput(page).fill('2')
      const before = await readCartCount(page)

      await addToCartButton(page).click()

      await expect(
        page
          .getByRole('status')
          .or(page.getByRole('alert'))
          .filter({ hasText: /added to (your )?cart/i }),
      ).toBeVisible()
      await expect
        .poll(() => readCartCount(page))
        .toBe(before + 2)
    })
  })

  test.describe('Wishlist', () => {
    test('saves and unsaves the shoe with the heart', async ({ page }) => {
      await openProductPage(page)
      const heart = wishlistButton(page)
      await expect(heart).toHaveAttribute('aria-pressed', 'false')

      await heart.click()
      await expect(heart).toHaveAttribute('aria-pressed', 'true')

      await heart.click()
      await expect(heart).toHaveAttribute('aria-pressed', 'false')
    })
  })

  test.describe('More information', () => {
    test('shows details, reviews and shipping side by side below the purchase options', async ({
      page,
    }) => {
      await openProductPage(page)
      const tabs = infoTablist(page)
      await expect(tabs).toBeVisible()

      const names = ['Details', 'Reviews', 'Shipping']
      const boxes = []
      for (const name of names) {
        await expect(infoTab(page, name)).toBeVisible()
        boxes.push(await infoTab(page, name).boundingBox())
      }
      expect(Math.abs(boxes[0].y - boxes[1].y)).toBeLessThan(2)
      expect(Math.abs(boxes[1].y - boxes[2].y)).toBeLessThan(2)
      expect(boxes[0].x).toBeLessThan(boxes[1].x)
      expect(boxes[1].x).toBeLessThan(boxes[2].x)

      const tablistBox = await tabs.boundingBox()
      for (const control of [
        photoCarousel(page),
        priceText(page),
        sizeCombobox(page),
        addToCartButton(page),
        wishlistButton(page),
      ]) {
        const box = await control.boundingBox()
        expect(tablistBox.y).toBeGreaterThanOrEqual(box.y + box.height)
      }
    })

    test('shows one section at a time', async ({ page }) => {
      await openProductPage(page)
      await expect(infoTab(page, 'Details')).toHaveAttribute(
        'aria-selected',
        'true',
      )
      await expect(page.getByRole('tabpanel')).toHaveCount(1)

      await infoTab(page, 'Reviews').click()
      await expect(infoTab(page, 'Reviews')).toHaveAttribute(
        'aria-selected',
        'true',
      )
      await expect(page.getByRole('tabpanel')).toHaveCount(1)
      await expect(page.getByRole('tabpanel')).toBeVisible()
    })
  })

  test.describe('Questions', () => {
    test('shows a few common questions with answers hidden until opened', async ({
      page,
    }) => {
      await openProductPage(page)
      const section = questionsRegion(page)
      await expect(section).toBeVisible()

      const questions = questionButtons(page)
      expect(await questions.count()).toBeGreaterThanOrEqual(3)

      const count = await questions.count()
      for (let i = 0; i < count; i++) {
        const question = questions.nth(i)
        await expect(question).toHaveAttribute('aria-expanded', 'false')
        const answerId = await question.getAttribute('aria-controls')
        expect(answerId).toBeTruthy()
        await expect(page.locator(`[id="${answerId}"]`)).toBeHidden()
      }
    })

    test('opens an answer when its question is chosen', async ({ page }) => {
      await openProductPage(page)
      const question = questionButtons(page).first()
      const answerId = await question.getAttribute('aria-controls')
      const answer = page.locator(`[id="${answerId}"]`)

      await question.click()
      await expect(question).toHaveAttribute('aria-expanded', 'true')
      await expect(answer).toBeVisible()
      await expect(answer).not.toBeEmpty()
    })
  })

  test.describe('Footer', () => {
    test('shows customer help, company and social media links at the bottom of the page', async ({
      page,
    }) => {
      await openProductPage(page)
      const footer = pageFooter(page)
      await expect(footer).toBeVisible()

      for (const heading of [/customer help/i, /company/i, /social media/i]) {
        await expect(footer.getByRole('heading', { name: heading })).toBeVisible()
      }

      await expect(
        footer.getByRole('link', {
          name: /instagram|facebook|youtube|x|twitter|linkedin|tiktok|threads/i,
        }),
      ).not.toHaveCount(0)

      const footerBox = await footer.boundingBox()
      const questionsBox = await questionsRegion(page).boundingBox()
      expect(footerBox.y).toBeGreaterThanOrEqual(
        questionsBox.y + questionsBox.height,
      )

      const pageHeight = await page.evaluate(
        () => document.documentElement.scrollHeight,
      )
      expect(footerBox.y + footerBox.height).toBeGreaterThanOrEqual(
        pageHeight - 2,
      )
    })
  })
})
